/*
 * tui.c — csm's full-screen interface on a pseudoterminal: keys and SGR
 * mouse reports go in, a small terminal emulator rebuilds the screen
 * from what comes out. Data, HOME and the config live below WORKDIR.
 *
 * Usage: tui CSM WORKDIR
 */
#define _XOPEN_SOURCE 700
#ifdef __APPLE__
#define _DARWIN_C_SOURCE	/* TIOCSCTTY */
#endif

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <locale.h>
#include <poll.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>
#include <wchar.h>

#include "test.h"

int test_checks;
int test_failures;

#define MAX_COLS 200
#define MAX_ROWS 60
#define WAIT_MS 5000		/* for the screen to show what is awaited */

/* Styles as SGR sets them. */
#define ST_BOLD 1
#define ST_REVERSE 2

struct cell {
	char text[8];		/* "" on the right half of a wide character */
	int fg;			/* the SGR code (31, 91, 38) or 0 for default */
	int fg_n, bg_n;		/* of the 256 (38;5;n, 48;5;n), or -1 */
	unsigned style;
};

/* What the terminal shows and what csm asked of it. */
struct term {
	int fd;			/* the master side */
	pid_t pid;
	size_t cols, rows, x, y;
	struct cell cells[MAX_ROWS][MAX_COLS];
	int fg, fg_n, bg_n;
	unsigned style;
	int alt, mouse, sgr_mouse;
	char pending[16384];	/* an incomplete sequence from the last read */
	size_t have;
	char *log;		/* everything csm wrote, for the way out */
	size_t log_len;
	int dark;		/* the background told on OSC 11 */
	int eof;
};

static char *work, *home, *config, *projects, *csm;

static void fail(const char *what)
{
	fprintf(stderr, "tui: %s: %s\n", what, strerror(errno));
	exit(2);
}

static char *join(const char *a, const char *b)
{
	size_t n = strlen(a) + strlen(b) + 2;
	char *p = malloc(n);

	if (p == NULL)
		fail("malloc");
	snprintf(p, n, "%s/%s", a, b);
	return p;
}

static void make_dir(const char *path)
{
	if (mkdir(path, 0700) != 0 && errno != EEXIST)
		fail(path);
}

static void write_text(const char *path, const char *text)
{
	FILE *fp = fopen(path, "w");

	if (fp == NULL)
		fail(path);
	fputs(text, fp);
	fclose(fp);
}

static int exists(const char *path)
{
	struct stat st;

	return lstat(path, &st) == 0;
}

/* The session directory name of an ASCII path, as Claude Code makes it. */
static char *encode(const char *path)
{
	char *out = strdup(path), *p;

	if (out == NULL)
		fail("strdup");
	for (p = out; *p != '\0'; p++)
		if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
		    (*p >= '0' && *p <= '9')))
			*p = '-';
	return out;
}

/* A project with a session directory holding sessions files of it. */
static void add_project(const char *name, int create, int sessions)
{
	char *path, *dir, *enc, *file, line[PATH_MAX + 256], base[24];
	int i;

	path = join(home, name);
	if (create)
		make_dir(path);
	enc = encode(path);
	dir = join(projects, enc);
	make_dir(dir);
	snprintf(line, sizeof line, "{\"type\":\"user\",\"cwd\":\"%s\","
	    "\"timestamp\":\"2026-10-30T10:00:00Z\",\"message\":{\"content\":"
	    "\"Hello %s\"}}\n", path, name);
	for (i = 0; i < sessions; i++) {
		snprintf(base, sizeof base, "s%d.jsonl", i);
		file = join(dir, base);
		write_text(file, line);
		free(file);
	}
	free(dir);
	free(enc);
	free(path);
}

static void setup(void)
{
	char *p, *file, text[3 * PATH_MAX + 128];
	char *alpha, *beta;

	home = join(work, "h");
	make_dir(home);
	config = join(home, ".claude");
	make_dir(config);
	projects = join(config, "projects");
	make_dir(projects);
	p = join(home, "p");
	make_dir(p);
	free(p);
	add_project("p/alpha", 1, 2);
	add_project("p/beta", 1, 1);
	add_project("p/gone", 0, 3);
	alpha = join(home, "p/alpha");
	beta = join(home, "p/beta");
	snprintf(text, sizeof text, "{\n  \"projects\": {\n    \"%s\": {},\n"
	    "    \"%s\": {}\n  }\n}\n", alpha, beta);
	/* With CLAUDE_CONFIG_DIR set, .claude.json is inside it. */
	file = join(config, ".claude.json");
	write_text(file, text);
	free(file);
	free(alpha);
	free(beta);
}

/* --- The emulator --- */

static void clear(struct term *t)
{
	size_t x, y;

	for (y = 0; y < MAX_ROWS; y++)
		for (x = 0; x < MAX_COLS; x++) {
			strcpy(t->cells[y][x].text, " ");
			t->cells[y][x].fg = 0;
			t->cells[y][x].fg_n = t->cells[y][x].bg_n = -1;
			t->cells[y][x].style = 0;
		}
}

static void reply(struct term *t, const char *s)
{
	ssize_t n = write(t->fd, s, strlen(s));

	(void)n;
}

/* The numbers of a CSI sequence; an empty one is 0. */
static size_t numbers(const char *p, long *v, size_t max)
{
	size_t n = 0;
	char *end;

	while (n < max) {
		v[n++] = strtol(p, &end, 10);
		if (*end != ';')
			break;
		p = end + 1;
	}
	return n;
}

static void sgr(struct term *t, const char *p)
{
	long v[32];
	size_t n, i;

	n = numbers(p, v, 32);
	for (i = 0; i < n; i++) {
		if (v[i] == 0) {
			t->fg = 0;
			t->fg_n = t->bg_n = -1;
			t->style = 0;
		} else if (v[i] == 1) {
			t->style |= ST_BOLD;
		} else if (v[i] == 7) {
			t->style |= ST_REVERSE;
		} else if ((v[i] >= 30 && v[i] <= 37) ||
		    (v[i] >= 90 && v[i] <= 97)) {
			t->fg = (int)v[i];
		} else if (v[i] == 39) {
			t->fg = 0;
		} else if (v[i] == 38 || v[i] == 48) {
			/* 38;5;n or 38;2;r;g;b: only one of the 256 is kept. */
			if (v[i] == 38)
				t->fg = 38;
			if (i + 2 < n && v[i + 1] == 5)
				*(v[i] == 38 ? &t->fg_n : &t->bg_n) = (int)v[i + 2];
			if (i + 1 < n)
				i += v[i + 1] == 5 ? 2 : 4;
		}
	}
}

static void modes(struct term *t, const char *p, int on)
{
	long v[16];
	size_t n, i;

	if (*p != '?')
		return;
	n = numbers(p + 1, v, 16);
	for (i = 0; i < n; i++) {
		if (v[i] == 1049)
			t->alt = on;
		else if (v[i] == 1000)
			t->mouse = on;
		else if (v[i] == 1006)
			t->sgr_mouse = on;
	}
}

static void csi(struct term *t, const char *params, char final)
{
	long r = 1, c = 1;
	size_t x;

	switch (final) {
	case 'H':
		if (sscanf(params, "%ld;%ld", &r, &c) < 1)
			r = c = 1;
		t->y = r > 0 ? (size_t)r - 1 : 0;
		t->x = c > 0 ? (size_t)c - 1 : 0;
		break;
	case 'm':
		sgr(t, params);
		break;
	case 'h':
	case 'l':
		modes(t, params, final == 'h');
		break;
	case 'J':
		clear(t);
		break;
	case 'K':
		for (x = t->x; x < t->cols && t->y < t->rows; x++)
			strcpy(t->cells[t->y][x].text, " ");
		break;
	}
}

/* One printable character at the cursor. */
static void put(struct term *t, const char *s, size_t len, int width)
{
	struct cell *c;

	if (t->x >= t->cols) {
		t->x = 0;
		if (t->y + 1 < t->rows)
			t->y++;
	}
	if (t->y >= t->rows || len >= sizeof c->text)
		return;
	c = &t->cells[t->y][t->x];
	memcpy(c->text, s, len);
	c->text[len] = '\0';
	c->fg = t->fg;
	c->fg_n = t->fg_n;
	c->bg_n = t->bg_n;
	c->style = t->style;
	if (width == 2 && t->x + 1 < t->cols) {
		t->cells[t->y][t->x + 1].text[0] = '\0';
		t->x++;
	}
	t->x++;
}

/* Bytes from csm; a sequence cut by the read waits for the rest. */
static void feed(struct term *t, const char *data, size_t n)
{
	char *p, *end, params[256];
	size_t used, k;
	mbstate_t ms;
	wchar_t wc;
	int w;

	t->log = realloc(t->log, t->log_len + n + 1);
	if (t->log == NULL)
		fail("realloc");
	memcpy(t->log + t->log_len, data, n);
	t->log_len += n;
	t->log[t->log_len] = '\0';
	if (t->have + n > sizeof t->pending)
		t->have = 0;
	memcpy(t->pending + t->have, data, n);
	t->have += n;
	p = t->pending;
	end = p + t->have;
	while (p < end) {
		if (*p == '\033') {
			if (p + 1 >= end)
				break;
			if (p[1] == '[') {
				for (k = 2; p + k < end &&
				    !((unsigned char)p[k] >= 0x40 &&
				    (unsigned char)p[k] <= 0x7e); k++)
					;
				if (p + k >= end)
					break;
				used = k - 2 < sizeof params ? k - 2 :
				    sizeof params - 1;
				memcpy(params, p + 2, used);
				params[used] = '\0';
				csi(t, params, p[k]);
				p += k + 1;
				continue;
			}
			if (p[1] == ']') {
				for (k = 2; p + k < end && p[k] != '\a' &&
				    !(p[k] == '\033' && p + k + 1 < end &&
				    p[k + 1] == '\\'); k++)
					;
				if (p + k >= end || (p[k] == '\033' &&
				    p + k + 1 >= end))
					break;
				if (k - 2 == 4 && memcmp(p + 2, "11;?", 4) == 0)
					reply(t, t->dark ?
					    "\033]11;rgb:0000/0000/0000\033\\" :
					    "\033]11;rgb:ffff/ffff/ffff\033\\");
				p += k + (p[k] == '\a' ? 1 : 2);
				continue;
			}
			p += 2;
			continue;
		}
		if (*p == '\r') {
			t->x = 0;
			p++;
			continue;
		}
		if (*p == '\n') {
			if (t->y + 1 < t->rows)
				t->y++;
			p++;
			continue;
		}
		if ((unsigned char)*p < 0x20) {
			p++;
			continue;
		}
		memset(&ms, 0, sizeof ms);
		used = mbrtowc(&wc, p, (size_t)(end - p), &ms);
		if (used == (size_t)-2)
			break;
		if (used == (size_t)-1 || used == 0) {
			p++;
			continue;
		}
		w = wcwidth(wc);
		put(t, p, used, w == 2 ? 2 : 1);
		p += used;
	}
	t->have = (size_t)(end - p);
	memmove(t->pending, p, t->have);
}

/* Reads what csm wrote for up to ms milliseconds; 0 when nothing came. */
static int pump(struct term *t, int ms)
{
	struct pollfd pfd;
	char buf[4096];
	ssize_t n;

	pfd.fd = t->fd;
	pfd.events = POLLIN;
	if (poll(&pfd, 1, ms) <= 0)
		return 0;
	n = read(t->fd, buf, sizeof buf);
	if (n <= 0) {
		/* EIO on the master once the other side is closed. */
		t->eof = 1;
		return 0;
	}
	feed(t, buf, (size_t)n);
	return 1;
}

static long now_ms(void)
{
	struct timespec ts;

	clock_gettime(CLOCK_MONOTONIC, &ts);
	return (long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

/* The text of row y; cols[i] is the column of byte i. */
static char *row(const struct term *t, size_t y, size_t *cols)
{
	static char line[MAX_COLS * 8 + 1];
	size_t x, len = 0, n, i;

	for (x = 0; x < t->cols; x++) {
		n = strlen(t->cells[y][x].text);
		if (cols != NULL)
			for (i = 0; i < n; i++)
				cols[len + i] = x;
		memcpy(line + len, t->cells[y][x].text, n);
		len += n;
	}
	line[len] = '\0';
	return line;
}

/* The column where text starts in row y, or -1. */
static long find_in(const struct term *t, size_t y, const char *text)
{
	static size_t cols[MAX_COLS * 8 + 1];
	char *line = row(t, y, cols), *at;

	at = strstr(line, text);
	return at != NULL ? (long)cols[at - line] : -1;
}

/* The first row with text, or -1. */
static long find_row(const struct term *t, const char *text)
{
	size_t y;

	for (y = 0; y < t->rows; y++)
		if (find_in(t, y, text) >= 0)
			return (long)y;
	return -1;
}

/* What a wait looks for: text in row y (-1: anywhere), or its absence. */
struct want {
	long y;
	const char *text;
	int absent;
};

static int holds(const struct term *t, const struct want *w)
{
	int found;

	found = w->y < 0 ? find_row(t, w->text) >= 0 :
	    find_in(t, (size_t)w->y, w->text) >= 0;
	return found != w->absent;
}

static void dump(const struct term *t)
{
	size_t y;

	for (y = 0; y < t->rows; y++)
		printf("tui: %2zu|%s\n", y, row(t, y, NULL));
}

/* Waits for the screen to show it; a failed wait counts as a failed check. */
static int await(struct term *t, long y, const char *text, int absent,
    const char *why)
{
	struct want w;
	long until = now_ms() + WAIT_MS;

	w.y = y;
	w.text = text;
	w.absent = absent;
	while (!holds(t, &w) && now_ms() < until && !t->eof)
		pump(t, 50);
	/* Whatever else came with the same frame. */
	while (pump(t, 20))
		;
	test_checks++;
	if (holds(t, &w))
		return 1;
	test_failures++;
	printf("tui: %s: row %ld %s \"%s\"\n", why, y,
	    absent ? "still has" : "lacks", text);
	dump(t);
	return 0;
}

#define AWAIT(y, text) await(&t, (y), (text), 0, #text)
#define AWAIT_GONE(y, text) await(&t, (y), (text), 1, #text)

static void send_keys(struct term *t, const char *s)
{
	size_t len = strlen(s);
	ssize_t n;

	while (len > 0) {
		n = write(t->fd, s, len);
		if (n <= 0)
			fail("write");
		s += n;
		len -= (size_t)n;
	}
}

/* Esc alone counts only after a pause; wait it out. */
static void send_esc(struct term *t)
{
	send_keys(t, "\033");
	pump(t, 120);
}

/* An SGR mouse report at 0-based x, y. */
static void mouse(struct term *t, int button, size_t x, size_t y, int press)
{
	char seq[64];

	snprintf(seq, sizeof seq, "\033[<%d;%zu;%zu%c", button, x + 1, y + 1,
	    press ? 'M' : 'm');
	send_keys(t, seq);
}

static void click(struct term *t, size_t x, size_t y)
{
	mouse(t, 0, x, y, 1);
	mouse(t, 0, x, y, 0);
}

static void resize(struct term *t, size_t cols, size_t rows)
{
	struct winsize ws;

	memset(&ws, 0, sizeof ws);
	ws.ws_col = (unsigned short)cols;
	ws.ws_row = (unsigned short)rows;
	t->cols = cols;
	t->rows = rows;
	clear(t);
	/* The system sends SIGWINCH to csm. */
	if (ioctl(t->fd, TIOCSWINSZ, &ws) != 0)
		fail("TIOCSWINSZ");
}

/* csm on a new pseudoterminal; -1 when the system gives none. */
static int start(struct term *t, size_t cols, size_t rows, int dark)
{
	struct winsize ws;
	char *slave;
	int fd;

	memset(t, 0, sizeof *t);
	t->cols = cols;
	t->rows = rows;
	t->dark = dark;
	clear(t);
	t->fd = posix_openpt(O_RDWR | O_NOCTTY);
	if (t->fd < 0)
		return -1;
	if (grantpt(t->fd) != 0 || unlockpt(t->fd) != 0 ||
	    (slave = ptsname(t->fd)) == NULL) {
		close(t->fd);
		return -1;
	}
	memset(&ws, 0, sizeof ws);
	ws.ws_col = (unsigned short)cols;
	ws.ws_row = (unsigned short)rows;
	t->pid = fork();
	if (t->pid < 0)
		fail("fork");
	if (t->pid == 0) {
		setsid();
		fd = open(slave, O_RDWR);
		if (fd < 0)
			_exit(127);
#ifdef TIOCSCTTY
		ioctl(fd, TIOCSCTTY, 0);
#endif
		ioctl(fd, TIOCSWINSZ, &ws);
		dup2(fd, 0);
		dup2(fd, 1);
		dup2(fd, 2);
		if (fd > 2)
			close(fd);
		close(t->fd);
		execl(csm, csm, (char *)NULL);
		_exit(127);
	}
	return 0;
}

/* Reads to the end and returns the exit status as waitpid gives it. */
static int finish(struct term *t)
{
	int status = 0;
	long until = now_ms() + WAIT_MS;

	while (!t->eof && now_ms() < until)
		pump(t, 50);
	if (waitpid(t->pid, &status, 0) < 0)
		fail("waitpid");
	close(t->fd);
	return status;
}

/* The terminal is back: no mouse, no alternate screen after the last entry. */
static int restored(const struct term *t)
{
	const char *enter = NULL, *p;

	for (p = t->log; (p = strstr(p, "\033[?1049h")) != NULL; p++)
		enter = p;
	return enter != NULL && strstr(enter, "\033[?1000l") != NULL &&
	    strstr(enter, "\033[?1049l") != NULL && !t->alt && !t->mouse;
}

/* The line of the panel border: the row full of line glyphs. */
static long border_row(const struct term *t)
{
	return find_row(t, "\342\224\200\342\224\200\342\224\200\342\224\200");
}

static char *read_file(const char *path)
{
	FILE *fp = fopen(path, "r");
	static char buf[4096];
	size_t n;

	if (fp == NULL)
		return NULL;
	n = fread(buf, 1, sizeof buf - 1, fp);
	buf[n] = '\0';
	fclose(fp);
	return buf;
}

/*
 * First run: the frame, the keys, the mouse, resizing, help and a move;
 * q saves the state.
 */
static void run_first(void)
{
	struct term t;
	char *path, *enc, *data;
	long y, x;
	int status;

	if (start(&t, 100, 30, 1) != 0) {
		printf("tui: no pseudoterminal here, TUI checks skipped\n");
		exit(0);
	}
	AWAIT(0, "csm \342\200\224 ~/.claude");
	CHECK(t.alt && t.mouse && t.sgr_mouse);
	AWAIT(1, "PROJECT \342\226\262");
	AWAIT(2, "~/p/alpha");
	AWAIT(3, "~/p/beta");
	AWAIT(4, "~/p/gone");
	/* A dark background: the dark theme, in the 256 without COLORTERM. */
	x = find_in(&t, 4, "orphaned");
	CHECK(x >= 0 && t.cells[4][x].fg_n == 203 &&
	    (t.cells[4][x].style & ST_BOLD));
	CHECK(t.cells[2][2].bg_n == 24 && t.cells[0][0].bg_n == 237);
	AWAIT(-1, "FIRST PROMPT");
	AWAIT(-1, "Hello p/alpha");
	CHECK(border_row(&t) == 15);

	/* Keys move the selection; the details follow. */
	send_keys(&t, "\033[B");
	AWAIT(-1, "Hello p/beta");
	CHECK(t.cells[3][2].bg_n == 24 && t.cells[2][2].bg_n == 234);
	send_keys(&t, "/gon");
	AWAIT(29, "Filter: gon");
	send_keys(&t, "\r");
	AWAIT(0, "Filter: gon");
	AWAIT_GONE(2, "~/p/alpha");
	AWAIT(2, "~/p/gone");
	send_esc(&t);
	AWAIT(2, "~/p/alpha");
	AWAIT_GONE(0, "Filter:");
	send_keys(&t, "o");
	AWAIT(1, "SESSIONS \342\226\274");
	AWAIT(2, "~/p/gone");

	/* The mouse: header, row, double click, the border. */
	x = find_in(&t, 1, "STATE");
	CHECK(x >= 0);
	click(&t, (size_t)x, 1);
	AWAIT(1, "STATE \342\226\262");
	y = find_row(&t, "~/p/beta");
	CHECK(y >= 2);
	click(&t, 10, (size_t)y);
	click(&t, 10, (size_t)y);
	AWAIT(29, "Tab or Esc");
	AWAIT(-1, "Hello p/beta");
	send_keys(&t, "\t");
	AWAIT_GONE(29, "Tab or Esc");
	mouse(&t, 0, 10, 15, 1);
	mouse(&t, 32, 10, 10, 1);
	mouse(&t, 0, 10, 10, 0);
	pump(&t, 200);
	while (pump(&t, 50))
		;
	CHECK(border_row(&t) == 10);
	/* Clicks on a button work as its key. */
	x = find_in(&t, 28, "Filter");
	CHECK(x >= 0);
	click(&t, (size_t)x, 28);
	AWAIT(29, "Filter: ");
	send_esc(&t);

	/* A new window size keeps the proportion; a tiny one says so. */
	resize(&t, 120, 40);
	AWAIT(38, "q Quit");
	CHECK(border_row(&t) == 13);
	resize(&t, 30, 8);
	AWAIT(0, "The terminal window is too");
	resize(&t, 100, 30);
	AWAIT(28, "q Quit");
	CHECK(border_row(&t) == 10);

	/* Help over the whole screen, scrolled by the wheel. */
	send_keys(&t, "?");
	AWAIT(0, "csm \342\200\224 help");
	AWAIT(1, "csm \342\200\224 manages");
	AWAIT(28, "Esc Close");
	mouse(&t, 65, 5, 5, 1);
	AWAIT_GONE(1, "csm \342\200\224 manages");
	send_esc(&t);
	AWAIT(1, "STATE");

	/* A move from the TUI changes the data in the work directory. */
	y = find_row(&t, "~/p/alpha");
	click(&t, 10, (size_t)y);
	AWAIT(-1, "Hello p/alpha");
	send_keys(&t, "m");
	AWAIT(29, "To: ~/p/alpha");
	send_keys(&t, "2\r");
	AWAIT(-1, "Plan of the move");
	send_keys(&t, "\r");
	AWAIT(29, "Moved: ~/p/alpha");
	path = join(home, "p/alpha2");
	CHECK(exists(path));
	enc = encode(path);
	free(path);
	path = join(projects, enc);
	CHECK(exists(path));
	free(path);
	path = join(home, "p/alpha");
	CHECK(!exists(path));
	free(path);
	path = join(config, ".claude.json");
	data = read_file(path);
	CHECK(data != NULL && strstr(data, "p/alpha\"") == NULL &&
	    strstr(data, "p/alpha2\"") != NULL);
	free(path);
	free(enc);
	AWAIT(-1, "~/p/alpha2");

	/* q: the terminal comes back and the state is saved. */
	send_keys(&t, "q");
	status = finish(&t);
	CHECK(WIFEXITED(status) && WEXITSTATUS(status) == 0);
	CHECK(restored(&t));
	free(t.log);
}

static char *state_path(void)
{
#ifdef __APPLE__
	return join(home, "Library/Application Support/csm/state");
#else
	return join(home, ".local/state/csm/state");
#endif
}

/*
 * Second run: the view of the first one, on a light background. A change
 * is saved after a moment of quiet; SIGTERM brings the terminal back.
 */
static void run_second(void)
{
	struct term t;
	char *path, *data;
	long x;
	int status;

	path = state_path();
	data = read_file(path);
	CHECK(data != NULL && strstr(data, "sort=state\n") != NULL &&
	    strstr(data, "split=320\n") != NULL &&
	    strstr(data, "selected=-") != NULL);
	if (start(&t, 100, 30, 0) != 0)
		fail("posix_openpt");
	AWAIT(1, "STATE \342\226\262");
	CHECK(border_row(&t) == 10);
	x = find_in(&t, 2, "~/p/alpha2");
	CHECK(x >= 0 && t.cells[2][2].bg_n == 153);
	x = find_in(&t, 4, "orphaned");
	CHECK(x >= 0 && t.cells[4][x].fg_n == 160);
	send_keys(&t, "/beta\r");
	AWAIT(0, "Filter: beta");
	pump(&t, 1000);
	data = read_file(path);
	CHECK(data != NULL && strstr(data, "filter=beta\n") != NULL);
	kill(t.pid, SIGTERM);
	status = finish(&t);
	CHECK(WIFSIGNALED(status) && WTERMSIG(status) == SIGTERM);
	CHECK(restored(&t));
	free(t.log);

	/* The filter saved in the quiet comes back too. */
	if (start(&t, 100, 30, 0) != 0)
		fail("posix_openpt");
	AWAIT(0, "Filter: beta");
	AWAIT(2, "~/p/beta");
	AWAIT_GONE(3, "~/p/");
	send_keys(&t, "q");
	status = finish(&t);
	CHECK(WIFEXITED(status) && WEXITSTATUS(status) == 0);
	free(t.log);
	free(path);
}

int main(int argc, char **argv)
{
	if (argc != 3) {
		fprintf(stderr, "usage: tui CSM WORKDIR\n");
		return 2;
	}
	csm = realpath(argv[1], NULL);
	work = realpath(argv[2], NULL);
	if (csm == NULL || work == NULL)
		fail("realpath");
	setlocale(LC_CTYPE, "en_US.UTF-8");
	setup();
	setenv("HOME", home, 1);
	setenv("CLAUDE_CONFIG_DIR", config, 1);
	setenv("TERM", "xterm-256color", 1);
	setenv("LC_ALL", "en_US.UTF-8", 1);
	setenv("CSM_CLAUDE_PROCESS", "csm-no-such-process", 1);
	unsetenv("NO_COLOR");
	unsetenv("COLORTERM");
	unsetenv("COLORFGBG");
	unsetenv("XDG_STATE_HOME");
	unsetenv("XDG_DATA_HOME");
	signal(SIGPIPE, SIG_IGN);

	run_first();
	run_second();

	printf("tui: %d checks, %d failed\n", test_checks, test_failures);
	return test_failures != 0;
}
